# ============================================================
# AEGIS NIDS - Phase 15 Deploy Script (IR/Forensic Part 2)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 15 - IR/Forensic Part 2"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase15_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
        Write-Host "  [OK] Backup created"
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] Line count: actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] Deployed: $ActualLines lines (expected $ExpectedLines)"
    }
}

$B64_1 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2146 -Base64Content $B64_1

$B64_2 = ''
Deploy-File -RelativePath "core/forensic_log.zig" -ExpectedLines 434 -Base64Content $B64_2

$B64_3 = ''
Deploy-File -RelativePath "core/bridge_init.zig" -ExpectedLines 487 -Base64Content $B64_3


Write-Host ""
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | ForEach-Object { Write-Host $_ }
if ($LASTEXITCODE -eq 0) {
    Write-Host "[BUILD] SUCCESS - All Phase 15 fixes applied"
} else {
    Write-Host "[BUILD] FAILED"
    exit 1
}

Write-Host ""
Write-Host "Summary of changes:"
Write-Host "  Phase 15 changes (IR/Forensic Part 2):"
Write-Host "    IR-04: Canonical timestamp schema (epoch_ms + monotonic_ns in NDJSON logs)"
Write-Host "    IR-06: Log rotation (100MB cap, keep 7 files, check every 60s)"
Write-Host "    IR-07: Full payload capture for Block events (logs/payloads/<sha256>.bin, dedup by hash)"
Write-Host "    IR-12: Status thread shutdown-responsive (1s poll instead of 30s blocking sleep)"
Write-Host "    IR-13: HMAC-SHA256 tamper-evidence on Rules.json (refuses load on mismatch)"
Write-Host "    B-10: UDP brain spool queue (1000 events, drops oldest + counter on full)"
Write-Host "    Effect: 6 IR/forensic improvements closing audit trail gaps"

Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"fix: best practices phase 15 - ir/forensic pt.2`""
Write-Host "  git push"
